using System.Web.Mvc;

namespace MvcSample.Controllers
{
    // As generated by the Visual Studio "MVC" template, plus Menu and Features.
    public class HomeController : Controller
    {
        public ActionResult Index()
        {
            return View();
        }

        public ActionResult About()
        {
            ViewBag.Message = "Your application description page.";

            return View();
        }

        public ActionResult Contact()
        {
            ViewBag.Message = "Your contact page.";

            return View();
        }

        // Child action rendered by the layout (Html.Action).
        [ChildActionOnly]
        public ActionResult Menu()
        {
            return PartialView("_Menu", new[] { "Home", "About", "Contact" });
        }

        // Razor features: inline and App_Code helpers, encoding, sections.
        public ActionResult Features()
        {
            ViewBag.Untrusted = "<script>alert('x')</script>";
            return View();
        }
    }
}
